using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Helpers;

public static class TestDbContextFactory
{
    public static SchoolContext Create(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;

        var context = new SchoolContext(options);
        context.Database.EnsureCreated();
        return context;
    }

    public static SchoolContext CreateWithData(string? dbName = null)
    {
        var context = Create(dbName);
        SeedData(context);
        return context;
    }

    public static void SeedData(SchoolContext context)
    {
        var instructor1 = new Instructor
        {
            ID = 1,
            LastName = "Smith",
            FirstMidName = "John",
            HireDate = new DateTime(2010, 1, 1),
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" }
        };

        var instructor2 = new Instructor
        {
            ID = 2,
            LastName = "Johnson",
            FirstMidName = "Jane",
            HireDate = new DateTime(2012, 6, 15),
            CourseAssignments = new List<CourseAssignment>()
        };

        context.Instructors.AddRange(instructor1, instructor2);

        var department = new Department
        {
            DepartmentID = 1,
            Name = "Computer Science",
            Budget = 100000,
            StartDate = new DateTime(2000, 1, 1),
            InstructorID = 1
        };

        context.Departments.Add(department);

        var course1 = new Course
        {
            CourseID = 1001,
            Title = "Intro to CS",
            Credits = 3,
            DepartmentID = 1,
            Department = department,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };

        var course2 = new Course
        {
            CourseID = 1002,
            Title = "Data Structures",
            Credits = 4,
            DepartmentID = 1,
            Department = department,
            Enrollments = new List<Enrollment>(),
            CourseAssignments = new List<CourseAssignment>()
        };

        context.Courses.AddRange(course1, course2);

        var student1 = new Student
        {
            ID = 1,
            LastName = "Doe",
            FirstMidName = "Alice",
            EnrollmentDate = new DateTime(2020, 9, 1),
            Enrollments = new List<Enrollment>()
        };

        var student2 = new Student
        {
            ID = 2,
            LastName = "Brown",
            FirstMidName = "Bob",
            EnrollmentDate = new DateTime(2021, 1, 15),
            Enrollments = new List<Enrollment>()
        };

        var student3 = new Student
        {
            ID = 3,
            LastName = "Adams",
            FirstMidName = "Carol",
            EnrollmentDate = new DateTime(2019, 9, 1),
            Enrollments = new List<Enrollment>()
        };

        context.Students.AddRange(student1, student2, student3);

        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 1001,
            StudentID = 1,
            Grade = Grade.A,
            Course = course1,
            Student = student1
        };

        context.Enrollments.Add(enrollment);
        student1.Enrollments.Add(enrollment);
        course1.Enrollments.Add(enrollment);

        // Course assignments
        var ca1 = new CourseAssignment { InstructorID = 1, CourseID = 1001 };
        var ca2 = new CourseAssignment { InstructorID = 1, CourseID = 1002 };
        context.CourseAssignments.AddRange(ca1, ca2);
        instructor1.CourseAssignments.Add(ca1);
        instructor1.CourseAssignments.Add(ca2);
        course1.CourseAssignments.Add(ca1);
        course2.CourseAssignments.Add(ca2);

        context.SaveChanges();
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Drain any leftover notifications from other tests (shared static queue)
        while (_service.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        _service.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage()
    {
        _service.SendNotification("Student", "1", "Alice Doe", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("Alice Doe", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityId()
    {
        _service.SendNotification("Course", "101", EntityOperation.UPDATE, "Teacher");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("ID: 101", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        _service.SendNotification("Student", "5", EntityOperation.DELETE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
    {
        _service.SendNotification("Department", "1", "CS", operation, "User");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains(expectedVerb, notification.Message);
        Assert.Equal(operation.ToString(), notification.Operation);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var notification = _service.ReceiveNotification();

        Assert.Null(notification);
    }

    [Fact]
    public void SendAndReceive_MultipleNotifications_FifoOrder()
    {
        _service.SendNotification("A", "1", EntityOperation.CREATE);
        _service.SendNotification("B", "2", EntityOperation.UPDATE);
        _service.SendNotification("C", "3", EntityOperation.DELETE);

        var first = _service.ReceiveNotification();
        var second = _service.ReceiveNotification();
        var third = _service.ReceiveNotification();

        Assert.Equal("A", first!.EntityType);
        Assert.Equal("B", second!.EntityType);
        Assert.Equal("C", third!.EntityType);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op in the in-memory implementation
        var ex = Record.Exception(() => _service.MarkAsRead(999));
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        var before = DateTime.Now.AddSeconds(-1);
        _service.SendNotification("Student", "1", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(1);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }
}

using ContosoUniversity.Controllers;
